CREATE POLICY "Owners read verification documents" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'seller-credentials' AND EXISTS (SELECT 1 FROM public.store_verifications v JOIN public.stores s ON s.id = v.store_id WHERE v.document_path = storage.objects.name AND v.user_id = auth.uid() AND s.owner_id = auth.uid()));
CREATE POLICY "Owners insert verification documents" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'seller-credentials' AND EXISTS (SELECT 1 FROM public.store_verifications v JOIN public.stores s ON s.id = v.store_id WHERE v.document_path = storage.objects.name AND v.user_id = auth.uid() AND s.owner_id = auth.uid()));
CREATE POLICY "Owners update pending verification documents" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'seller-credentials' AND EXISTS (SELECT 1 FROM public.store_verifications v JOIN public.stores s ON s.id = v.store_id WHERE v.document_path = storage.objects.name AND v.user_id = auth.uid() AND s.owner_id = auth.uid() AND v.status = 'pending')) WITH CHECK (bucket_id = 'seller-credentials' AND EXISTS (SELECT 1 FROM public.store_verifications v JOIN public.stores s ON s.id = v.store_id WHERE v.document_path = storage.objects.name AND v.user_id = auth.uid() AND s.owner_id = auth.uid() AND v.status = 'pending'));
CREATE POLICY "Owners delete pending verification documents" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'seller-credentials' AND EXISTS (SELECT 1 FROM public.store_verifications v JOIN public.stores s ON s.id = v.store_id WHERE v.document_path = storage.objects.name AND v.user_id = auth.uid() AND s.owner_id = auth.uid() AND v.status = 'pending'));